package com.mfrp.plens.model;import jakarta.persistence.*;@Entity public class ProjectSubmission{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private String podName,title,technologyStack,documentationLink;@Column(length=4000)private String problemStatement,objectives;private int alignmentScore,overlapScore;@Enumerated(EnumType.STRING)private DecisionStatus decisionStatus=DecisionStatus.PENDING;public Long getId(){return id;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getPodName(){return podName;}public void setPodName(String v){podName=v;}public String getProblemStatement(){return problemStatement;}public void setProblemStatement(String v){problemStatement=v;}public String getObjectives(){return objectives;}public void setObjectives(String v){objectives=v;}public String getTechnologyStack(){return technologyStack;}public void setTechnologyStack(String v){technologyStack=v;}public String getDocumentationLink(){return documentationLink;}public void setDocumentationLink(String v){documentationLink=v;}public int getAlignmentScore(){return alignmentScore;}public void setAlignmentScore(int v){alignmentScore=v;}public int getOverlapScore(){return overlapScore;}public void setOverlapScore(int v){overlapScore=v;}public DecisionStatus getDecisionStatus(){return decisionStatus;}public void setDecisionStatus(DecisionStatus v){decisionStatus=v;}}
